 static Map<StormCollisionPages.Section,StormCollisionPages.Page> terrain(String kind){
  var result=new LinkedHashMap<StormCollisionPages.Section,StormCollisionPages.Page>();
  for(int sectionX=-6;sectionX<=6;sectionX++)for(int sectionY=-4;sectionY<=15;sectionY++)for(int sectionZ=-6;sectionZ<=6;sectionZ++){
   int[] cells=new int[128];for(int localY=0;localY<16;localY++)for(int localZ=0;localZ<16;localZ++)for(int localX=0;localX<16;localX++){
    int worldX=sectionX*16+localX,worldY=sectionY*16+localY,worldZ=sectionZ*16+localZ;
    boolean solid=switch(kind){case "Sealed"->true;case "Sparse"->worldY<0||(worldX>=0&&worldX<=1&&worldZ>=-10&&worldZ<10&&worldY<24);case "Slope"->worldY<(int)Math.floor(worldX*.25)+2+(worldZ>8&&worldZ<14?2:0);case "Dense"->worldY<20;case "Wall"->worldY<0||(worldX>=0&&worldX<=1&&Math.abs(worldZ)<50&&worldY<100);case "Air","NoEligible"->worldY< -48;default->worldY<0;};
    if(solid){int cell=localX|(localZ<<4)|(localY<<8);cells[cell>>>5]|=1<<(cell&31);}
   }result.put(new StormCollisionPages.Section(sectionX,sectionY,sectionZ),StormCollisionPages.page(1,cells));
  }return result;
 }
 static ClientboundStormWavePacket normalized(ClientboundStormWavePacket packet){
  float start=packet.startSec(),centerX=packet.centerX(),centerY=packet.centerY(),centerZ=packet.centerZ();float[] path=packet.path().clone();for(int index=0;index<path.length;index+=3){path[index]-=centerX;path[index+1]-=centerY;path[index+2]-=centerZ;}
  return new ClientboundStormWavePacket(packet.waveId(),packet.epoch(),0,packet.waveSeed(),packet.targetEntityId(),packet.swordTier(),1,12288,0,packet.assembleSec()-start,packet.lockSec()-start,packet.diveUntilSec()-start,packet.crownX()-centerX,packet.crownY()-centerY,packet.crownZ()-centerZ,32,packet.members(),path,packet.landings(),1,1,packet.groupEnds(),0,0,0,packet.orientation(),packet.direction(),0,0);
 }
 static BitSet bitset(ByteBuffer words){long[] values=new long[words.capacity()/8];for(int index=0;index<values.length;index++)values[index]=words.getLong(index*8);return BitSet.valueOf(values);}
