    var completions=bitset(DomePathGpuValidation.range(state,StarfallGpuBuffers.COMPLETIONS,384));completions.andNot(retired);retired.or(completions);if(!completions.isEmpty()){gpu.trackReturn(packet,completions.toLongArray());gpu.completed(packet.waveId(),completions.toLongArray());}
    var clocks=DomePathGpuValidation.range(state,StarfallGpuBuffers.DOME_FLOW_STATE,132);int flowCount=0;for(int flow=0;flow<66;flow++){float value=clocks.getFloat(flow*8+4);if(Float.isFinite(value)){flowCount++;if(frozen[flow]>=0)check(value==frozen[flow],"Frozen flow changed during navigation");frozen[flow]=value;}}
    if(flowCount!=publishedFlows||!completions.isEmpty()){publishedFlows=flowCount;gpu.rebuild(new ClientboundStormWavePacket[]{packet.withGatherFlows(new DomeGatherState(frozen)),null,null,null});}
    trace.add(seconds+","+ready+","+eligible+","+retired.cardinality()+","+metrics.getInt(32)+","+metrics.getInt(36)+","+metrics.getInt(40)+","+maximumWait);
    locked=DomeGatherRules.ready(ready,eligible,DomeGatherRules.elapsedTicks(seconds,0),DomeGatherRules.durationTicks(0,deadline));if(locked){
     readyMask=bitset(DomePathGpuValidation.range(state,StarfallGpuBuffers.GATHER_READY,384));eligibleMask=bitset(DomePathGpuValidation.range(state,StarfallGpuBuffers.GATHER_ELIGIBLE,384));check(DomeGatherRules.valid(readyMask,eligibleMask,12288,seconds,0,deadline),"Terrain masks failed readiness validation");var overlap=(BitSet)eligibleMask.clone();overlap.and(retired);check(overlap.isEmpty(),"Retired rank reentered the denominator");
     bind(0,output);bind(22,reports);put(reports,bytes(4+16384*24));gpu.bind(contact,true);f(contact,"uTimeSec",seconds);ui(contact,"uLocalWaveMask",1);dispatch(contact,(population+63)/64);var feedback=read(reports,4+16384*24);var reportedReady=new BitSet();var reportedEligible=new BitSet();for(int record=0;record<feedback.getInt(0);record++){int offset=4+record*24,type=Math.round(feedback.getFloat(offset));if(type!=-4&&type!=-5)continue;int word=Math.round(feedback.getFloat(offset+8)),bits=Math.round(feedback.getFloat(offset+12))|(Math.round(feedback.getFloat(offset+16))<<16);for(int bit=0;bit<32;bit++)if((bits&(1<<bit))!=0)(type==-4?reportedReady:reportedEligible).set(word*32+bit);}check(readyMask.equals(reportedReady)&&eligibleMask.equals(reportedEligible),"Actual feedback disagreed with final terrain masks");
    }
